using System;
using System.Net;
using System.Text;
using System.IO;

class HelloWorldServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");

        listener.Start();

        Console.WriteLine("Serveur HTTP démarré sur le port 8080...");
        Console.WriteLine("Appuyez sur Entrée pour arrêter le serveur...");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.AbsolutePath == "/hello")
            {
                string response = "<html><body>Hello, world!</body></html>";
                context.Response.StatusCode = 200;
                context.Response.ContentType = "text/html";
                byte[] buffer = Encoding.UTF8.GetBytes(response);
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
            }
            else
            {
                context.Response.StatusCode = 404;
                context.Response.StatusDescription = "Page not found";
            }

            context.Response.Close();
        }
    }
}
```
